package app.dawnbreaker.mobile;
import android.webkit.CookieManager;import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import androidx.webkit.*;
public class DawnCloudActivity extends androidx.appcompat.app.AppCompatActivity{
 private WebView web;private final ExecutorService worker=Executors.newFixedThreadPool(3);private String script="";private boolean injectedAtStart;
 static final Map<String,String> PROVIDERS=new HashMap<>();static{PROVIDERS.put("baidu","https://pan.baidu.com/disk/main");PROVIDERS.put("ali","https://www.alipan.com/drive/file/all");PROVIDERS.put("mobile","https://yun.139.com/w/");PROVIDERS.put("tianyi","https://cloud.189.cn/web/main/");PROVIDERS.put("xunlei","https://pan.xunlei.com/");PROVIDERS.put("quark","https://pan.quark.cn/");PROVIDERS.put("uc","https://drive.uc.cn/");PROVIDERS.put("pan123","https://www.123pan.com/");}
 static boolean cloudHost(String host){if(host==null)return false;for(String d:Arrays.asList("baidu.com","aliyundrive.com","alipan.com","139.com","189.cn","xunlei.com","quark.cn","uc.cn","123pan.com","123pan.cn","123684.com","123865.com","123952.com","123912.com"))if(host.equals(d)||host.endsWith("."+d))return true;return false;}
 static String validateStart(String provider,String value)throws Exception{if(!PROVIDERS.containsKey(provider))throw new Exception();String source=value==null||value.isEmpty()?PROVIDERS.get(provider):value;URL u=new URL(source);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||!cloudHost(u.getHost()))throw new Exception();return source;}
 static boolean messageAllowed(Uri origin,boolean mainFrame){return mainFrame&&"https".equals(origin.getScheme())&&(origin.getPort()==-1||origin.getPort()==443)&&cloudHost(origin.getHost());}
 Set<String> origins(){Set<String> rules=new HashSet<>();for(String domain:Arrays.asList("baidu.com","aliyundrive.com","alipan.com","139.com","189.cn","xunlei.com","quark.cn","uc.cn","123pan.com","123pan.cn","123684.com","123865.com","123952.com","123912.com")){rules.add("https://"+domain);rules.add("https://*."+domain);}return rules;}
 void registerPort()throws Exception{
  if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))throw new Exception("请先更新 Android System WebView，再使用网盘助手");
  GMBridge actions=new GMBridge();WebViewCompat.addWebMessageListener(web,"DawnCloudPort",origins(),(view,message,origin,mainFrame,reply)->{
   if(!messageAllowed(origin,mainFrame)||message.getData()==null||message.getData().length()>2100000)return;
   try{JSONObject payload=new JSONObject(message.getData());String id=payload.getString("id"),command=payload.getString("command");if(!id.matches("[A-Za-z0-9-]{1,80}"))return;JSONObject options=payload.optJSONObject("options");if(options==null)options=new JSONObject();final JSONObject o=options;
    worker.execute(()->{JSONObject response=new JSONObject();try{response.put("id",id);JSONObject result=new JSONObject();switch(command){case"request":result=http(o);break;case"clipboard":actions.clipboard(o.optString("text"));break;case"open":actions.open(o.optString("url"));break;case"download":DawnCloudActivity.this.download(o,null);break;default:throw new Exception();}response.put("value",result);}catch(Exception e){try{response.put("id",id).put("error","网盘请求失败，请检查登录、访问权限或网络");}catch(Exception ignored){}}runOnUiThread(()->{if(web!=null)reply.postMessage(response.toString());});});
   }catch(Exception ignored){}
  });
 }
 String asset(String name)throws Exception{try(InputStream in=getAssets().open("linkswift/"+name)){return new String(DawnWarpService.read(in,2*1024*1024),StandardCharsets.UTF_8);}}
 @SuppressWarnings("SetJavaScriptEnabled") @Override public void onCreate(Bundle b){super.onCreate(b);try{String source=validateStart(getIntent().getStringExtra("provider"),getIntent().getStringExtra("url"));LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setBackgroundColor(0xfff8f8f5);LinearLayout bar=new LinearLayout(this);Button back=new Button(this);back.setText("返回");back.setOnClickListener(v->{if(web.canGoBack())web.goBack();else finish();});Button close=new Button(this);close.setText("关闭网盘助手");close.setOnClickListener(v->finish());bar.addView(back);bar.addView(close);layout.addView(bar);web=new WebView(this);layout.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(layout);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setSupportMultipleWindows(false);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setUserAgentString("Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/142.0.0.0 Safari/537.36");CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);registerPort();
  StringBuilder js=new StringBuilder("window.__dawnCloudResources="+new JSONObject().put("SwalLigt",asset("light.css")).put("SwalDark",asset("dark.css"))+";\n");for(String name:Arrays.asList("android-port.js","runtime.js","jquery.js","sweetalert.js","md5.js","sha256.js","LinkSwift.user.js"))js.append(asset(name)).append("\n;\n");script=js.toString();if(WebViewFeature.isFeatureSupported(WebViewFeature.DOCUMENT_START_SCRIPT)){WebViewCompat.addDocumentStartJavaScript(web,script,origins());injectedAtStart=true;}
  web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(!r.getUrl().getScheme().equals("https"))return true;return false;}@Override public void onPageFinished(WebView v,String url){if(!injectedAtStart&&cloudHost(Uri.parse(url).getHost()))v.evaluateJavascript(script,null);CookieManager.getInstance().flush();}});web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public boolean onJsAlert(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(DawnCloudActivity.this).setMessage(message).setPositiveButton("确定",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}@Override public boolean onJsPrompt(WebView v,String url,String message,String defaultValue,JsPromptResult result){EditText input=new EditText(DawnCloudActivity.this);input.setText(defaultValue);new AlertDialog.Builder(DawnCloudActivity.this).setMessage(message).setView(input).setPositiveButton("确定",(d,w)->result.confirm(input.getText().toString())).setNegativeButton("取消",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}});web.setDownloadListener((url,ua,disp,mime,length)->worker.execute(()->{try{download(new JSONObject().put("url",url).put("name",URLUtil.guessFileName(url,disp,mime)),null);}catch(Exception e){toast("下载失败，请重新解析直链");}}));getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){@Override public void handleOnBackPressed(){if(web.canGoBack())web.goBack();else finish();}});web.loadUrl(source);
 }catch(Exception e){Toast.makeText(this,e.getMessage()!=null&&e.getMessage().contains("WebView")?e.getMessage():"网盘助手初始化失败",Toast.LENGTH_LONG).show();finish();}}
 void toast(String message){runOnUiThread(()->Toast.makeText(this,message,Toast.LENGTH_LONG).show());}
 static URL publicURL(String value)throws Exception{URL u=new URL(value);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||u.getPort()!=-1&&u.getPort()!=443)throw new Exception("仅支持公网 HTTPS 地址");for(InetAddress a:InetAddress.getAllByName(u.getHost())){byte[] b=a.getAddress();if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress()||b.length==16&&(b[0]&0xe0)!=0x20||b.length==4&&(b[0]&255)==100&&((b[1]&255)>=64&&(b[1]&255)<=127))throw new Exception("不能访问本地或内网地址");}return u;}
 void download(JSONObject o,JSONObject inherited)throws Exception{URL url=publicURL(o.getString("url"));DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url.toString()));String cookies=CookieManager.getInstance().getCookie(url.toString());if(cookies!=null)request.addRequestHeader("Cookie",cookies);request.addRequestHeader("User-Agent",web.getSettings().getUserAgentString());JSONObject headers=o.optJSONObject("headers");if(headers!=null)for(Iterator<String> i=headers.keys();i.hasNext();){String k=i.next(),value=headers.optString(k);if(Arrays.asList("user-agent","referer","authorization","cookie").contains(k.toLowerCase(Locale.ROOT))&&!value.contains("\n")&&!value.contains("\r"))request.addRequestHeader(k,value);}String filename=o.optString("name",URLUtil.guessFileName(url.toString(),null,null)).replaceAll("[\\\\/:\\r\\n]","_");request.setTitle(filename).setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);if(Build.VERSION.SDK_INT>=29)request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,filename);else request.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,filename);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(request);toast("已加入系统下载，可在通知栏查看进度");}
 JSONObject http(JSONObject o)throws Exception{String raw=o.getString("url");Uri uri=Uri.parse(raw);if(Arrays.asList("localhost","127.0.0.1","::1","[::1]").contains(uri.getHost())){JSONObject payload=new JSONObject(o.optString("data"));if(!payload.optString("method").equals("aria2.addUri"))throw new Exception("仅适配 Aria2 添加下载，不访问本机 RPC");JSONArray params=payload.getJSONArray("params");JSONArray urls=null;JSONObject config=null;for(int n=0;n<params.length();n++){if(params.optJSONArray(n)!=null)urls=params.getJSONArray(n);if(params.optJSONObject(n)!=null)config=params.getJSONObject(n);}if(urls==null)throw new Exception("缺少下载地址");JSONObject headers=new JSONObject();if(config!=null&&config.optJSONArray("header")!=null){JSONArray hs=config.getJSONArray("header");for(int n=0;n<hs.length();n++){String[] pair=hs.getString(n).split(":\\s*",2);if(pair.length==2)headers.put(pair[0],pair[1]);}}download(new JSONObject().put("url",urls.getString(0)).put("headers",headers),null);return new JSONObject().put("status",200).put("responseText",new JSONObject().put("jsonrpc","2.0").put("id",payload.opt("id")).put("result",UUID.randomUUID()).toString()).put("responseHeaders","").put("finalUrl",raw);}
  URL url=publicURL(raw);HttpURLConnection c=null;try{for(int tries=0;tries<6;tries++){url=publicURL(url.toString());c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(Math.min(o.optInt("timeout",30000),120000));String method=o.optString("method","GET").toUpperCase(Locale.ROOT);if(!Arrays.asList("GET","POST","PUT","DELETE","HEAD","PATCH","OPTIONS").contains(method))throw new Exception("请求方法无效");c.setRequestMethod(method);String cookies=CookieManager.getInstance().getCookie(url.toString());if(cookies!=null)c.setRequestProperty("Cookie",cookies);JSONObject headers=o.optJSONObject("headers");if(headers!=null)for(Iterator<String> i=headers.keys();i.hasNext();){String k=i.next(),v=headers.optString(k);if(!Arrays.asList("host","content-length","connection").contains(k.toLowerCase(Locale.ROOT))&&!v.contains("\r")&&!v.contains("\n"))c.setRequestProperty(k,v);}if(!Arrays.asList("GET","HEAD").contains(method)&&o.has("data")){byte[] data=o.getString("data").getBytes(StandardCharsets.UTF_8);if(data.length>2e6)throw new Exception("请求内容过大");c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(data);}}int status=c.getResponseCode();if(status>=300&&status<400&&c.getHeaderField("Location")!=null){url=new URL(url,c.getHeaderField("Location"));c.disconnect();c=null;continue;}InputStream input=status>=400?c.getErrorStream():c.getInputStream();byte[] data=input==null?new byte[0]:DawnWarpService.read(input,32*1024*1024);if(input!=null)input.close();JSONObject result=new JSONObject().put("status",status).put("statusText",c.getResponseMessage()).put("finalUrl",url.toString());StringBuilder h=new StringBuilder();for(Map.Entry<String,List<String>> e:c.getHeaderFields().entrySet())if(e.getKey()!=null)for(String v:e.getValue())h.append(e.getKey()).append(": ").append(v).append("\r\n");result.put("responseHeaders",h.toString());if(Arrays.asList("blob","arraybuffer").contains(o.optString("responseType")))result.put("base64",android.util.Base64.encodeToString(data,android.util.Base64.NO_WRAP));else result.put("responseText",new String(data,StandardCharsets.UTF_8));return result;}throw new Exception("网盘重定向过多");}finally{if(c!=null)c.disconnect();}}
 class GMBridge{
  public void request(String id,String options){worker.execute(()->{try{JSONObject result=http(new JSONObject(options));runOnUiThread(()->web.evaluateJavascript("window.__dawnCloudReply("+JSONObject.quote(id)+",null,"+result+")",null));}catch(Exception e){runOnUiThread(()->web.evaluateJavascript("window.__dawnCloudReply("+JSONObject.quote(id)+","+JSONObject.quote("网盘请求失败，请检查登录、访问权限或网络")+",null)",null));}});}
  public void clipboard(String text){runOnUiThread(()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("网盘直链",text));toast("已复制");});}
  public void open(String value){runOnUiThread(()->{try{URL u=new URL(value);if(!u.getProtocol().equals("https"))return;if(cloudHost(u.getHost()))web.loadUrl(value);else startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(value)));}catch(Exception ignored){}});}
  public void download(String options){worker.execute(()->{try{DawnCloudActivity.this.download(new JSONObject(options),null);}catch(Exception e){toast("下载地址不可用，请重新解析");}});}
 }
 @Override protected void onDestroy(){if(web!=null){if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))WebViewCompat.removeWebMessageListener(web,"DawnCloudPort");web.destroy();web=null;}worker.shutdownNow();super.onDestroy();}
}
